+import { csvCell } from '../lib/text.js';
+import { createEventCard } from './event-card.js';
+import { buildRoster } from './roster.js';
+
+export function exportRosterCsv(event, signups) {
+  const { title, dateLabel } = createEventCard(event);
+  const rows = ['event,date,name,email'];
+  for (const { name, email } of buildRoster(signups)) {
+    rows.push([title, dateLabel, name, email].map(csvCell).join(','));
+  }
+  return rows.join('\n') + '\n';
+}

